/* Stage 6 UI. Workflow transitions and task state live in demo-workflow.js. */
if(!document.querySelector('[data-agent-runtime-css]')){const link=document.createElement('link');link.rel='stylesheet';link.href='agent-runtime.css?v=1';link.dataset.agentRuntimeCss='true';document.head.append(link)}
if(!window.makoraRealAgents&&!document.querySelector('[data-agent-runtime-script]')){const script=document.createElement('script');script.src='agent-runtime-ui.js?v=2';script.dataset.agentRuntimeScript='true';document.head.append(script)}
window.createAgentPlan = function(root, mascot) {
  const workflow=window.makoraDemoWorkflow;
  const viewKey='makora.workspace-view.v1';
  let savedView={};try{savedView=JSON.parse(localStorage.getItem(viewKey))||{}}catch{}
  let boardTab='map', selectedTask=workflow.getTasks()[0]?.id||null, moduleId='app', testRows=[], agentMode=savedView.agentMode==='real'?'real':'demo';
  let moved=!!savedView.planMoved, drag=null;
  const board=document.createElement('section');board.className='agent-plan-board';board.hidden=true;board.setAttribute('aria-label','Демонстрационная подготовка агентной разработки');
  board.innerHTML=`<img class="agent-board-shadow" src="analysis-board.png" alt="" draggable="false"><img class="agent-board-art" src="analysis-board.png" alt="" draggable="false"><nav class="agent-board-tabs" aria-label="Последовательные шаги разработки"><button type="button" data-workflow-step="skeleton">01 <span>Скелет</span></button><button type="button" data-workflow-step="decomposition">02 <span>Задачи</span></button><button type="button" data-workflow-step="map">03 <span>Карта</span></button><button type="button" data-workflow-step="simulation">04 <span>Запуск</span></button></nav><div class="agent-board-frame"><header class="agent-board-header"><div><small>ЭТАП 06 · <span data-agent-mode-label>ДЕМО</span></small><h2>Скелет проекта</h2></div><div class="agent-mode-switch" role="group" aria-label="Режим разработки"><button type="button" data-agent-mode="demo">DEMO</button><button type="button" data-agent-mode="real">REAL</button></div><button type="button" data-agent-expand aria-label="Развернуть доску" title="Развернуть доску">⛶</button></header><main class="agent-board-content" tabindex="0"></main><footer class="agent-board-footer"><span data-agent-status>УЧЕБНЫЙ СЦЕНАРИЙ · РЕАЛЬНЫЕ АГЕНТЫ НЕ ЗАПУЩЕНЫ</span><button type="button" data-agent-primary></button></footer></div>`;
  root.append(board);
  const content=board.querySelector('.agent-board-content'),status=board.querySelector('[data-agent-status]'),primary=board.querySelector('[data-agent-primary]');
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const clamp=(n,min,max)=>Math.max(min,Math.min(max,n));
  const motion={x:0,y:0,targetX:0,targetY:0,velocity:0,rotation:0,frame:0,last:0};
  const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');
  function paint(){board.style.left=motion.x+'px';board.style.top=motion.y+'px';board.style.setProperty('--agent-tilt',motion.rotation+'deg')}
  function settle(){cancelAnimationFrame(motion.frame);motion.frame=0;motion.x=motion.targetX;motion.y=motion.targetY;motion.velocity=motion.rotation=0;paint()}
  function animate(now){motion.frame=0;if(!root.isConnected||board.hidden||board.classList.contains('agent-expanded')||reducedMotion.matches){settle();return}const dt=Math.min(.06,Math.max(0,(now-motion.last)/1000));motion.last=now;const smooth=1-Math.exp(-dt*11);motion.x+=(motion.targetX-motion.x)*smooth;motion.y+=(motion.targetY-motion.y)*smooth;motion.rotation+=(clamp(motion.velocity*.006,-3,3)-motion.rotation)*(1-Math.exp(-dt*7));if(!drag){motion.velocity*=Math.exp(-dt*7);motion.rotation*=Math.exp(-dt*2.3)}paint();if(drag||Math.abs(motion.targetX-motion.x)>.1||Math.abs(motion.targetY-motion.y)>.1||Math.abs(motion.velocity)>.1||Math.abs(motion.rotation)>.01)motion.frame=requestAnimationFrame(animate);else settle()}
  function startMotion(){if(reducedMotion.matches){settle();return}if(!motion.frame){motion.last=performance.now();motion.frame=requestAnimationFrame(animate)}}
  function saveView(){try{const latest=JSON.parse(localStorage.getItem(viewKey))||{};savedView={...latest,planMoved:moved,planX:motion.targetX,planY:motion.targetY,planExpanded:board.classList.contains('agent-expanded'),agentStep:workflow.getStep(),agentSubtab:boardTab,agentTask:selectedTask,agentMode};localStorage.setItem(viewKey,JSON.stringify(savedView))}catch{}}
  function position(){if(board.hidden||board.classList.contains('agent-expanded'))return;const rect=mascot.getBoundingClientRect(),width=window.innerWidth<=900?Math.min(560,window.innerWidth-16):Math.min(610,Math.max(390,rect.left-26));board.style.width=width+'px';if(moved){motion.targetX=clamp(Number(savedView.planX)||0,0,Math.max(0,innerWidth-board.offsetWidth));motion.targetY=clamp(Number(savedView.planY)||0,0,Math.max(8,innerHeight-board.offsetHeight));settle();return}motion.targetX=innerWidth<=900?8:Math.max(8,rect.left-width-22);motion.targetY=innerWidth<=900?8:Math.max(8,Math.min(innerHeight-board.offsetHeight-8,rect.top+rect.height/2-board.offsetHeight/2));settle()}
  function stageOrder(){return ['skeleton','decomposition','map','simulation']}
  function updateTabs(){const step=workflow.getStep(),index=stageOrder().indexOf(workflow.getHighestUnlockedStep());board.classList.toggle('agent-git-active',step==='map'&&boardTab==='gitflow');board.classList.toggle('agent-real-mode',agentMode==='real');board.querySelectorAll('[data-agent-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.agentMode===agentMode);b.setAttribute('aria-pressed',String(b.dataset.agentMode===agentMode))});board.querySelector('[data-agent-mode-label]').textContent=agentMode==='real'?'REAL':'ДЕМО';board.querySelectorAll('[data-workflow-step]').forEach(btn=>{const i=stageOrder().indexOf(btn.dataset.workflowStep),locked=i>index;btn.disabled=locked;btn.classList.toggle('active',step===btn.dataset.workflowStep);btn.classList.toggle('complete',i<index);if(step===btn.dataset.workflowStep)btn.setAttribute('aria-current','step');else btn.removeAttribute('aria-current')});const title={skeleton:'Скелет проекта',decomposition:'Декомпозиция',map:boardTab==='gitflow'?'Gitflow':'Карта разработки',simulation:'Симуляция разработки'};board.querySelector('.agent-board-header h2').textContent=agentMode==='real'?'Агентная разработка':title[step]||'Этап 6'}
  function fileTree(){return `<div class="agent-file-tree"><button data-module="app"><code>src/</code><span>учебная структура · подобрана под этот кейс</span></button><button data-module="app"><code>├─ app-shell.ts</code><span>основа интерфейса</span></button><button data-module="source"><code>├─ data/space-source.ts</code><span>адаптер к мок-источнику</span></button><button data-module="catalog"><code>├─ catalog/space-catalog.ts</code><span>готовый контракт, реализация — задача T02</span></button><button data-module="search"><code>├─ search/space-search.ts</code><span>заглушка до T03</span></button><button data-module="integration"><code>└─ app/search-flow.ts</code><span>заглушка до T04</span></button><button data-module="mocks"><code>mocks/fixtures/spaces.json</code><span>исходный источник демонстрационных записей</span></button></div>`}
  const modules={app:{title:'Каркас приложения',status:'Основа подготовлена',files:['src/app-shell.ts','03_architecture.md'],contracts:['Web UI → SpaceSource']},source:{title:'Адаптер мок-данных',status:'Подключён к исходным фикстурам',files:['src/data/space-source.ts','mocks/fixtures/spaces.json'],contracts:['Space','GET /spaces']},catalog:{title:'Каталог пространств',status:'Контракт определён · реализацию выполняет T02',files:['03_contracts/openapi.yaml','mocks/fixtures/spaces.json','mocks/fixtures/empty.json'],contracts:['Space','GET /spaces']},search:{title:'Интерфейс поиска',status:'Заглушка · будет реализована в T03',files:['02_user_flow.mmd','03_contracts/openapi.yaml'],contracts:['Space','GET /spaces']},integration:{title:'Основной поток',status:'Заглушка · будет реализована в T04',files:['02_task_flow.mmd','03_test_plan.md'],contracts:['GET /spaces','Error']},mocks:{title:'Мок-данные',status:'Утверждённые исходные фикстуры',files:['mocks/fixtures/spaces.json','mocks/scenarios.json','mocks/fixtures/empty.json','mocks/fixtures/stale.json','mocks/fixtures/invalid.json'],contracts:['Space','Error']}};
  function skeleton(){const s=workflow.getState(),checks=s.agent.skeletonChecks;content.innerHTML=`<p class="agent-note">Подготовленный пример на основе согласованных материалов «Тихого кампуса». Структура относится только к этому учебному проекту.</p><div class="agent-skeleton-layout"><section><h3>Дерево проекта</h3>${fileTree()}</section><section class="agent-module-info"><span class="agent-kicker">ВЫБРАННЫЙ МОДУЛЬ</span><h3 data-module-title>${esc(modules[moduleId]?.title)}</h3><p data-module-status>${esc(modules[moduleId]?.status)}</p><strong>Файлы и артефакты</strong><ul data-module-files>${modules[moduleId]?.files.map(x=>`<li><code>${esc(x)}</code></li>`).join('')}</ul><strong>Контракты</strong><ul data-module-contracts>${modules[moduleId]?.contracts.map(x=>`<li><code>${esc(x)}</code></li>`).join('')}</ul></section></div><section class="agent-contract-flow"><h3>Поток данных и границы модулей</h3><div><span>Search UI <small>заглушка · T03</small></span><b>→</b><span>Space Catalog <small>T02</small></span><b>→</b><span>Mock Adapter <small>читает fixtures/</small></span></div><p>Контракт: <code>GET /spaces</code> возвращает <code>Space[]</code>. Код настоящего приложения здесь не создаётся и не запускается.</p></section><section class="agent-skeleton-checks"><header><div><span class="agent-kicker">ПРОВЕРКА СКЕЛЕТА</span><p>Проверим доступность фикстур и их соответствие OpenAPI в текущем браузере.</p></div><button type="button" data-skeleton-check>Проверить основание ↻</button></header>${checks?`<ul class="agent-check-results">${checks.results.map(x=>`<li class="${x.ok?'ok':'fail'}"><b>${x.ok?'✓':'×'}</b><span><strong>${esc(x.name)}</strong><small>${esc(x.detail)}</small></span></li>`).join('')}</ul><small class="agent-stamp">Проверено ${esc(new Date(checks.checkedAt).toLocaleString('ru-RU'))} · только проверки артефактов и фикстур</small>`:'<p class="agent-check-empty">Проверки ещё не выполнялись.</p>'}</section>`;
    content.querySelectorAll('[data-module]').forEach(btn=>btn.onclick=()=>{moduleId=btn.dataset.module;selectedSkeletonModule()});
    content.querySelector('[data-skeleton-check]').onclick=runSkeletonChecks;
    primary.hidden=false;primary.textContent='Скелет подготовлен — перейти к декомпозиции';primary.disabled=!checks?.results?.length||checks.results.some(x=>!x.ok);primary.onclick=()=>{const result=workflow.approveSkeleton();if(!result.ok){announce(result.error);return}workflow.openStep('decomposition');render()};
    status.textContent=checks?.results?.length&&checks.results.every(x=>x.ok)?'ОСНОВАНИЕ ПРОВЕРЕНО · НУЖНО УТВЕРЖДЕНИЕ':'ОСНОВАНИЕ ЕЩЁ НЕ ПРОВЕРЕНО · ДЕМО';
  }
  function selectedSkeletonModule(){const info=modules[moduleId];content.querySelector('[data-module-title]').textContent=info.title;content.querySelector('[data-module-status]').textContent=info.status;content.querySelector('[data-module-files]').innerHTML=info.files.map(x=>`<li><code>${esc(x)}</code></li>`).join('');content.querySelector('[data-module-contracts]').innerHTML=info.contracts.map(x=>`<li><code>${esc(x)}</code></li>`).join('');content.querySelectorAll('[data-module]').forEach(x=>x.classList.toggle('selected',x.dataset.module===moduleId))}
  async function runSkeletonChecks(){const button=content.querySelector('[data-skeleton-check]');button.disabled=true;button.textContent='Проверяем…';const results=[];try{const response=await fetch('./mocks/fixtures/spaces.json',{cache:'no-store'});const spaces=await response.json();results.push({name:'Исходная фикстура spaces.json',ok:response.ok&&Array.isArray(spaces)&&spaces.length===20,detail:response.ok?`Прочитано ${Array.isArray(spaces)?spaces.length:0} записей из mocks/fixtures/spaces.json.`:'Файл недоступен.'});const ctx=window.makoraStage3.getContext(),schema=String(ctx.openapi);const schemaOk=/^\s{4}Space:/m.test(schema)&&/^\s{4}Error:/m.test(schema)&&/\/spaces:\s*\n\s+get:/m.test(schema);const validate=window.planValidateFixtures;const fixtureValidation=typeof validate==='function'?validate(schema,spaces):{ok:spaces.every(x=>x&&x.id&&x.name&&x.building&&Number.isFinite(x.capacity))};results.push({name:'Контракт OpenAPI ↔ Space',ok:schemaOk&&fixtureValidation.ok,detail:schemaOk&&fixtureValidation.ok?'Схема Space и поля фикстуры согласованы.':'Схема или структура фикстуры не прошла проверку.'});const scenariosResponse=await fetch('./mocks/scenarios.json',{cache:'no-store'});const scenarios=await scenariosResponse.json();results.push({name:'Сценарии Mock API',ok:scenariosResponse.ok&&Array.isArray(scenarios)&&scenarios.length===5&&scenarios.some(x=>x.id==='server_error'),detail:scenariosResponse.ok?`Найдено ${Array.isArray(scenarios)?scenarios.length:0} сценариев, включая отказ источника.`:'Файл сценариев недоступен.'})}catch(error){results.push({name:'Чтение артефактов',ok:false,detail:error.message})}workflow.recordSkeletonChecks(results);render();}
  function taskSummary(t){return `<div class="agent-task-summary"><span><b>Цель</b>${esc(t.goal)}</span><span><b>Результат</b>${esc(t.result)}</span><span><b>Зависимости</b>${esc(t.dependsOn.join(', ')||'Нет')}</span><span><b>Контракты</b>${t.contracts.map(x=>`<code>${esc(x)}</code>`).join(' ')}</span><span><b>Моки</b>${t.mocks.map(x=>`<code>${esc(x)}</code>`).join(' ')}</span><span><b>Готово, когда</b>${esc(t.acceptance)}</span><span><b>Ветка · предлагаемая</b><code>${esc(t.branch)}</code></span></div>`}
  const textFields=[['title','Название'],['goal','Цель'],['result','Результат'],['acceptance','Критерий готовности'],['branch','Предлагаемая Git-ветка']];
  const arrayFields=[['inputArtifacts','Входные артефакты'],['contracts','Контракты · выберите из OpenAPI'],['mocks','Необходимые моки'],['outputs','Файлы-результаты проекта']];
  function taskEditor(t){const contracts=workflow.contractOptions();return `<div class="agent-editor-heading"><span class="agent-kicker">ЗАДАНИЕ ${esc(t.id)}</span><button type="button" data-add-task>＋ Добавить задачу</button></div><div class="agent-task-cards">${workflow.getTasks().map(x=>`<button type="button" data-select-edit="${esc(x.id)}" class="${x.id===t.id?'selected':''}"><b>${esc(x.id)}</b><span>${esc(x.title)}</span></button>`).join('')}</div><form class="agent-task-editor" data-task-form="${esc(t.id)}"><div class="agent-edit-grid">${textFields.map(([name,label])=>`<label><span>${esc(label)}</span><input data-task-field="${name}" value="${esc(t[name])}" /></label>`).join('')}<label class="wide"><span>Зависимости · запрещены циклы и самоссылки</span><div class="agent-dep-options">${workflow.getTasks().filter(x=>x.id!==t.id).map(x=>`<label><input type="checkbox" data-task-dep="${esc(x.id)}" ${t.dependsOn.includes(x.id)?'checked':''}><span>${esc(x.id)} · ${esc(x.title)}</span></label>`).join('')}</div></label>${arrayFields.map(([name,label])=>name==='contracts'?`<fieldset class="wide"><legend>${esc(label)}</legend><div class="agent-dep-options">${contracts.map(x=>`<label><input type="checkbox" data-task-array="contracts" value="${esc(x)}" ${t.contracts.includes(x)?'checked':''}><span><code>${esc(x)}</code></span></label>`).join('')}${t.contracts.filter(x=>!contracts.includes(x)).map(x=>`<p class="agent-validation-error">Неизвестный контракт: ${esc(x)}</p>`).join('')}</div></fieldset>`:`<label class="wide"><span>${esc(label)} · по одному на строку</span><textarea data-task-array="${name}">${esc((t[name]||[]).join('\n'))}</textarea></label>`).join('')}<label class="wide"><span>Промпт Builder</span><textarea data-task-field="builderPrompt">${esc(t.builderPrompt)}</textarea></label><label class="wide"><span>Промпт независимого Test Designer</span><textarea data-task-field="testPrompt">${esc(t.testPrompt)}</textarea></label><label class="wide"><span>Промпт Reviewer</span><textarea data-task-field="reviewerPrompt">${esc(t.reviewerPrompt)}</textarea></label><label class="agent-checkbox"><input type="checkbox" data-task-field="testUi" ${t.testUi?'checked':''}> Для блока нужен внутренний тестовый интерфейс</label></div></form><section class="agent-validation"><b>Проверка декомпозиции</b><ul data-graph-errors></ul></section>`}
  function decomposition(){const tasks=workflow.getTasks();if(!selectedTask||!tasks.some(t=>t.id===selectedTask))selectedTask=tasks[0]?.id;const t=tasks.find(x=>x.id===selectedTask);content.innerHTML=`<p class="agent-note">Редактируемые задания для будущих агентов. Связи и обязательные поля проверяются до утверждения.</p>${taskEditor(t)}<div class="agent-demo-callout">Демо-кейс «Тихий кампус» · изменение задач снимает прежнее согласование карты и останавливает устаревшую симуляцию.</div>`;
    content.querySelectorAll('[data-select-edit]').forEach(b=>b.onclick=()=>{selectedTask=b.dataset.selectEdit;decomposition()});content.querySelector('[data-add-task]').onclick=()=>{selectedTask=workflow.addTask();decomposition()};
    const form=content.querySelector('[data-task-form]');
    form.addEventListener('input',e=>{const el=e.target,name=el.dataset.taskField;if(!name||name==='testUi')return;const value=el.value;workflow.updateTask(t.id,{[name]:value});showGraphErrors()});
    form.addEventListener('change',e=>{const el=e.target;if(el.dataset.taskDep){const deps=[...form.querySelectorAll('[data-task-dep]:checked')].map(x=>x.dataset.taskDep);workflow.updateTask(t.id,{dependsOn:deps});decomposition();return}if(el.dataset.taskArray==='contracts'){const contracts=[...form.querySelectorAll('[data-task-array="contracts"]:checked')].map(x=>x.value);workflow.updateTask(t.id,{contracts});decomposition();return}if(el.dataset.taskField==='testUi'){workflow.updateTask(t.id,{testUi:el.checked});return}if(el.dataset.taskArray){const arr=el.value.split(/\n|,/).map(x=>x.trim()).filter(Boolean);workflow.updateTask(t.id,{[el.dataset.taskArray]:arr});showGraphErrors()}});
    showGraphErrors();primary.hidden=false;primary.textContent='Проверить и утвердить декомпозицию';primary.disabled=workflow.validateGraph().length>0;primary.onclick=()=>{const result=workflow.approveDecomposition();if(!result.ok){announce(result.error);showGraphErrors();return}workflow.openStep('map');boardTab='map';render()};status.textContent=workflow.validateGraph().length?'ДЕКОМПОЗИЦИЯ С ОШИБКАМИ · НУЖНО ИСПРАВИТЬ':'ЗАДАЧИ И КОНТРАКТЫ СОГЛАСУЮТСЯ';
  }
  function showGraphErrors(){const list=content.querySelector('[data-graph-errors]');if(!list)return;const errors=workflow.validateGraph();list.innerHTML=errors.length?errors.map(x=>`<li class="agent-validation-error">${esc(x)}</li>`).join(''):'<li class="ok">✓ Зависимости существуют, циклов и конфликтов результатов нет; ссылки на OpenAPI найдены.</li>';primary.disabled=errors.length>0;}
  function levels(tasks){const result={},byId=new Map(tasks.map(t=>[t.id,t]));function level(id,stack=new Set()){if(result[id]!==undefined)return result[id];if(stack.has(id))return 0;stack.add(id);const deps=byId.get(id)?.dependsOn||[];result[id]=deps.length?Math.max(...deps.map(x=>byId.has(x)?level(x,stack)+1:0)):0;stack.delete(id);return result[id]}tasks.forEach(t=>level(t.id));return result}
  function mapGraph(){const tasks=workflow.getTasks(),depth=levels(tasks),max=Math.max(0,...Object.values(depth)),rows=Array.from({length:max+1},(_,i)=>tasks.filter(t=>depth[t.id]===i));return `<div class="agent-map-summary"><span>ПОРЯДОК ЗАПУСКА · ГРАФ ИЗ ${tasks.length} ЗАДАЧ</span><span>${rows.filter(r=>r.length>1).map(r=>r.map(t=>t.id).join(' + ')).join(' · ')||'Параллельные блоки появятся по структуре зависимостей'}</span></div><div class="agent-dag-shell"><svg class="agent-dag-edges" aria-hidden="true"></svg><div class="agent-dag">${rows.map((row,i)=>`<div class="agent-dag-layer" data-dag-layer="${i}">${row.map(t=>`<button type="button" class="agent-dag-node" data-map-task="${esc(t.id)}"><span>${esc(t.id)} · ${esc(t.branch)}</span><strong>${esc(t.title)}</strong><small>${t.dependsOn.length?'Ждёт: '+esc(t.dependsOn.join(', ')):'Первый запуск'} · Builder / Reviewer</small></button>`).join('')}</div>`).join('')}</div></div><p class="agent-dag-note">Задача T04 не запускается, пока T02 и T03 не интегрированы после Reviewer. Ветки только предполагаются; Git-команды не выполняются.</p><section class="agent-map-detail" data-map-detail></section>`}
  function drawDag(){const shell=content.querySelector('.agent-dag-shell'),svg=content.querySelector('.agent-dag-edges');if(!shell||!svg)return;const b=shell.getBoundingClientRect();svg.setAttribute('viewBox',`0 0 ${b.width} ${b.height}`);svg.setAttribute('width',b.width);svg.setAttribute('height',b.height);const tasks=workflow.getTasks(),byId=new Map(tasks.map(t=>[t.id,t]));let paths='';for(const task of tasks){const target=content.querySelector(`[data-map-task="${CSS.escape(task.id)}"]`);if(!target)continue;const tr=target.getBoundingClientRect();for(const dep of task.dependsOn){const source=content.querySelector(`[data-map-task="${CSS.escape(dep)}"]`);if(!source)continue;const sr=source.getBoundingClientRect(),x1=sr.left-b.left+sr.width/2,y1=sr.bottom-b.top,x2=tr.left-b.left+tr.width/2,y2=tr.top-b.top;paths+=`<path d="M${x1} ${y1} C${x1} ${y1+(y2-y1)*.48},${x2} ${y1+(y2-y1)*.52},${x2} ${y2}"/>`}}svg.innerHTML=`<defs><marker id="dag-arrow" viewBox="0 0 8 8" refX="6" refY="4" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0 L8 4 L0 8" fill="#aaa"/></marker></defs><g>${paths.replaceAll('<path ','<path marker-end="url(#dag-arrow)" ')}</g>`;}
  function detailCard(t){return `<div class="agent-card-title"><span>${esc(t.id)}</span><h3>${esc(t.title)}</h3></div><p class="agent-card-demo">Задание подготовлено для внешнего Builder, Test Designer и Reviewer. Ни один агент не запущен.</p>${taskSummary(t)}<details class="agent-prompts"><summary>Промпты и условия передачи</summary><h4>Builder</h4><pre>${esc(t.builderPrompt)}</pre><h4>Независимый Test Designer</h4><pre>${esc(t.testPrompt)}</pre><h4>Reviewer</h4><pre>${esc(t.reviewerPrompt)}</pre></details><button type="button" class="agent-secondary" data-edit-task="${esc(t.id)}">Вернуться к редактированию задания</button>`}
  function gitflowSvg(){
    const tasks=workflow.getTasks(),lane=34,featureCount=tasks.length,developY=24+featureCount*lane,releaseY=developY+lane,hotfixY=releaseY+lane,mainY=hotfixY+lane,height=mainY+40,width=940,branchStart=270,branchEnd=585;
    const label=(kind,name,y,detail='')=>`<g class="git-label git-label-${kind}"><title>${esc(detail||name)}</title><rect x="12" y="${y-10}" width="112" height="20" rx="3"/><text x="21" y="${y+4}">${esc(name)}</text></g>`;
    const labels=tasks.map((t,i)=>label('feature',`feature · ${t.id}`,24+i*lane,t.branch)).join('')+label('develop','develop',developY)+label('release','release',releaseY)+label('hotfix','hotfix',hotfixY)+label('main','main',mainY);
    const lanes=Array.from({length:featureCount},(_,i)=>`<path class="git-lane git-lane-feature" d="M140 ${24+i*lane} H916"/>`).join('')+`<path class="git-lane git-lane-develop" d="M140 ${developY} H916"/><path class="git-lane git-lane-release" d="M140 ${releaseY} H916"/><path class="git-lane git-lane-hotfix" d="M140 ${hotfixY} H916"/><path class="git-lane git-lane-main" d="M140 ${mainY} H916"/>`;
    const features=tasks.map((t,i)=>{
      const y=24+i*lane,branchX=branchStart+i*12,commitX=395+i*13,mergeX=555+i*11;
      return `<g class="git-feature-flow"><path d="M188 ${developY} C${branchX-34} ${developY},${branchX-20} ${y},${branchX} ${y} H${commitX} C${mergeX-28} ${y},${mergeX-20} ${developY},${mergeX} ${developY}"/><circle class="git-commit git-commit-feature" cx="${branchX}" cy="${y}" r="7"/><circle class="git-commit git-commit-feature" cx="${commitX}" cy="${y}" r="7"/><circle class="git-commit git-commit-develop" cx="${mergeX}" cy="${developY}" r="7"/></g>`
    }).join('');
    const releaseX=680,hotfixX=790;
    return `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Gitflow: feature-ветки задач объединяются в develop, затем релиз попадает в main"><defs><marker id="git-arrow" viewBox="0 0 8 8" refX="6" refY="4" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0 L8 4 L0 8" fill="#a9a3b0"/></marker></defs><g class="git-lanes">${lanes}</g><g class="git-flow-lines"><path class="git-line-main" d="M188 ${mainY} C205 ${mainY},170 ${developY},188 ${developY}"/><path class="git-line-develop" d="M188 ${developY} H900"/><path class="git-line-release" d="M${releaseX} ${developY} C${releaseX+20} ${developY},${releaseX-14} ${releaseY},${releaseX} ${releaseY} H820 C842 ${releaseY},842 ${mainY},860 ${mainY}"/><path class="git-line-hotfix" d="M450 ${mainY} C468 ${mainY},460 ${hotfixY},${hotfixX} ${hotfixY} C${hotfixX+26} ${hotfixY},${hotfixX+8} ${mainY},${hotfixX+30} ${mainY} M${hotfixX} ${hotfixY} C${hotfixX+27} ${hotfixY},${hotfixX+29} ${developY},${hotfixX+55} ${developY}"/>${features}</g><g class="git-labels">${labels}</g><g class="git-commits"><circle class="git-commit git-commit-main" cx="188" cy="${mainY}" r="8"/><circle class="git-commit git-commit-develop" cx="188" cy="${developY}" r="8"/><circle class="git-commit git-commit-release" cx="${releaseX}" cy="${releaseY}" r="8"/><circle class="git-commit git-commit-hotfix" cx="${hotfixX}" cy="${hotfixY}" r="8"/><circle class="git-commit git-commit-main" cx="860" cy="${mainY}" r="8"/></g><g class="git-versions"><g><rect x="165" y="${mainY+12}" width="48" height="17" rx="2"/><text x="189" y="${mainY+24}" text-anchor="middle">start</text></g><g><rect x="835" y="${mainY+12}" width="48" height="17" rx="2"/><text x="859" y="${mainY+24}" text-anchor="middle">v1.0</text></g></g></svg>`
  }
  function map(){updateTabs();content.innerHTML=`<div class="agent-map-subtabs"><button type="button" data-map-view="map" class="${boardTab==='map'?'active':''}">Карта задач</button><button type="button" data-map-view="gitflow" class="${boardTab==='gitflow'?'active':''}">Gitflow</button></div>${boardTab==='map'?mapGraph():`<p class="agent-note">Предполагаемые ветки утверждаемого плана. Имена веток и слияния не создаются автоматически.</p><div class="agent-git-diagram">${gitflowSvg()}</div><div class="agent-git-caption">Feature-ветки выводятся из текущих карточек задач · develop → release → main</div>`}`;content.querySelectorAll('[data-map-view]').forEach(b=>b.onclick=()=>{boardTab=b.dataset.mapView;saveView();map()});if(boardTab==='map'){const selected=workflow.getTask(selectedTask)||workflow.getTasks()[0];content.querySelector('[data-map-detail]').innerHTML=selected?detailCard(selected):'';content.querySelectorAll('[data-map-task]').forEach(b=>b.onclick=()=>{selectedTask=b.dataset.mapTask;workflow.selectSimulationTask(selectedTask);content.querySelector('[data-map-detail]').innerHTML=detailCard(workflow.getTask(selectedTask));content.querySelectorAll('[data-map-task]').forEach(n=>n.classList.toggle('selected',n.dataset.mapTask===selectedTask));saveView()});content.querySelector('[data-edit-task]').onclick=()=>{selectedTask=content.querySelector('[data-edit-task]').dataset.editTask;workflow.openStep('decomposition');render()};requestAnimationFrame(drawDag)}primary.hidden=false;primary.textContent='Утвердить карту разработки';primary.disabled=workflow.validateGraph().length>0;primary.onclick=()=>{const result=workflow.approveMap();if(!result.ok){announce(result.error);return}workflow.openStep('simulation');render()};status.textContent='ПЛАНИРУЕМЫЕ ВЕТКИ · КАРТА НЕ УТВЕРЖДЕНА'}

  function statusLabel(value){return ({blocked:'Заблокирована',ready:'Готова к запуску',testing_preparation:'Test Designer готовит тесты',implementing:'Builder выполняет задачу',reviewing:'Ожидает Reviewer',fixing:'Исправление после замечания',passed:'Ревью пройдено · ждёт интеграции',failed:'Три попытки не прошли · эскалация',integrated:'Интегрирована'})[value]||value}
  function testLab(){return `<section class="agent-test-lab"><header><span class="agent-kicker">ВНУТРЕННЯЯ ПЕСОЧНИЦА · НЕ ПУБЛИЧНЫЙ ЭКРАН</span><button type="button" data-close-lab>Свернуть</button></header><p>Каталог читает исходный файл <code>mocks/fixtures/spaces.json</code>. Эта мини-проверка не меняет фикстуру.</p><div class="agent-lab-filters"><label>Корпус<select data-lab-building><option value="">Все</option><option value="main">Главный</option><option value="north">Северный</option></select></label><label>Поиск<input data-lab-query placeholder="Название или ID"></label></div><p data-lab-count>Читаем фикстуру…</p><div class="agent-lab-results" data-lab-results></div></section>`}
  async function loadTestLab(){const host=content.querySelector('[data-test-lab]');if(!host)return;host.innerHTML=testLab();try{const r=await fetch('./mocks/fixtures/spaces.json',{cache:'no-store'});testRows=await r.json();renderLabResults()}catch(e){host.querySelector('[data-lab-count]').textContent='Фикстуру не удалось прочитать: '+e.message}const lab=content.querySelector('.agent-test-lab');lab.querySelector('[data-close-lab]').onclick=()=>{host.remove()};lab.querySelector('[data-lab-building]').onchange=renderLabResults;lab.querySelector('[data-lab-query]').oninput=renderLabResults}
  function renderLabResults(){const lab=content.querySelector('.agent-test-lab');if(!lab)return;const building=lab.querySelector('[data-lab-building]').value,query=lab.querySelector('[data-lab-query]').value.trim().toLowerCase();const filtered=testRows.filter(x=>(!building||x.building===building)&&(!query||`${x.id} ${x.name}`.toLowerCase().includes(query)));lab.querySelector('[data-lab-count]').textContent=`${filtered.length} из ${testRows.length} пространств · данные source=demo`;lab.querySelector('[data-lab-results]').innerHTML=filtered.slice(0,8).map(x=>`<article><span><strong>${esc(x.name)}</strong><small>${esc(x.id)} · ${esc(x.building)}</small></span><b>${esc(x.availableSeats??'—')} мест</b><em>${esc(x.status)}</em></article>`).join('')||'<p>По этим условиям ничего не найдено.</p>'}
  function simulation(){const s=workflow.getState().agent.simulation,tasks=workflow.getTasks(),ready=workflow.getReadyTasks(),allIntegrated=s.started&&tasks.every(t=>workflow.getTaskStatus(t.id)==='integrated');content.innerHTML=`<p class="agent-note">Ручное продвижение демо-событий. Builder, Test Designer и Reviewer — роли симулятора; внешние агенты, команды и настоящие Git-ветки не запускаются.</p><section class="agent-run-controls"><div><strong>${s.started?(s.mode==='escalation'?'Сценарий эскалации':'Основной сценарий'):'Выберите учебный сценарий'}</strong><small>${s.started?'Можно вести несколько независимых задач параллельно. Каждое изменение статуса требует действия пользователя.':'Сначала доступна T01; T02 и T03 откроются после её интеграции.'}</small></div>${!s.started?`<button type="button" data-start-run>Начать демонстрацию</button><button type="button" data-start-escalation>Сценарий трёх ошибок</button>`:`<button type="button" data-reset-run>Сбросить только симуляцию</button>`}</section>${s.started?`<div class="agent-parallel-note">${ready.length>1?'ПАРАЛЛЕЛЬНО ДОСТУПНЫ: '+ready.join(' · '):ready.length===1?'СЕЙЧАС ДОСТУПНА: '+ready[0]:'ОЖИДАНИЕ ЗАВИСИМОСТЕЙ · '+tasks.filter(t=>workflow.getTaskStatus(t.id)==='blocked').map(t=>t.id).join(', ')}</div>`:''}<div class="agent-sim-grid"><section class="agent-sim-list"><h3>Задачи и зависимости</h3>${tasks.map(t=>{const st=workflow.getTaskStatus(t.id);return `<button type="button" data-sim-task="${esc(t.id)}" class="agent-sim-task ${st} ${s.activeTask===t.id?'selected':''}"><span class="agent-state-mark">${st==='integrated'?'✓':st==='ready'?'●':st==='blocked'?'○':'◒'}</span><span><strong>${esc(t.id)} · ${esc(t.title)}</strong><small>${esc(statusLabel(st))} · ждёт ${esc(t.dependsOn.join(', ')||'ничего')}</small></span></button>`}).join('')}</section><section class="agent-sim-detail" data-sim-detail></section></div>${allIntegrated?`<section class="agent-completion-report"><span class="agent-kicker">ИТОГ ДЕМО · ВСЕ ЗАДАЧИ УСЛОВНО ИНТЕГРИРОВАНЫ</span><h3>Что готово</h3><ul>${tasks.map(t=>`<li><b>${esc(t.id)} · ${esc(t.title)}</b><span>${esc((t.outputs||[]).join(', '))} — заглушка условно заменена</span></li>`).join('')}</ul><p><b>Моки:</b> исходные фикстуры <code>mocks/fixtures/</code> остаются источником данных.</p><p><b>Проверки:</b> независимые тесты, критерии и ревью отражены как учебные события; исполняемый код не запускался.</p><p><b>Ограничения:</b> агенты, ветки и merge не создавались. Интеграция существует только внутри демо.</p></section>`:''}<details class="agent-event-history" ${s.started?'':'open'}><summary>История событий · ${workflow.exportHistory().length}</summary><ol>${workflow.exportHistory().slice().reverse().map(ev=>`<li><time>${esc(new Date(ev.at).toLocaleTimeString('ru-RU'))}</time><b>${esc(ev.taskId||'FLOW')}</b><span>${esc(ev.detail)}</span></li>`).join('')||'<li>Событий пока нет.</li>'}</ol></details><div class="agent-history-return"><span>Режим эскалации после трёх неудачных попыток запускает передачу решения Макоре и запрещает интеграцию.</span>${s.started?'<button type="button" data-confirm-reset>Очистить состояние симуляции</button>':''}</div>`;
    if(!s.started){primary.hidden=true;status.textContent=workflow.getState().agent.mapApproved?'КАРТА УТВЕРЖДЕНА · АГЕНТЫ ЕЩЁ НЕ ЗАПУЩЕНЫ':'СНАЧАЛА УТВЕРДИТЕ КАРТУ';content.querySelector('[data-start-run]').onclick=()=>{const r=workflow.startSimulation('normal');if(!r.ok){announce(r.error);return}render()};content.querySelector('[data-start-escalation]').onclick=()=>{const r=workflow.startSimulation('escalation');if(!r.ok){announce(r.error);return}render()};return}
    primary.hidden=true;status.textContent=s.tasks&&Object.keys(s.tasks).length&&tasks.every(t=>workflow.getTaskStatus(t.id)==='integrated')?'ВСЕ ЗАДАЧИ УСЛОВНО ИНТЕГРИРОВАНЫ · ДЕМО':'СИМУЛЯЦИЯ УПРАВЛЯЕТСЯ ПОЛЬЗОВАТЕЛЕМ · ДЕМО';content.querySelectorAll('[data-sim-task]').forEach(b=>b.onclick=()=>{selectedTask=b.dataset.simTask;workflow.selectSimulationTask(selectedTask);simulation()});content.querySelector('[data-reset-run]').onclick=()=>{content.querySelector('.agent-history-return').classList.add('confirming');content.querySelector('[data-confirm-reset]').focus()};content.querySelector('[data-confirm-reset]').onclick=()=>{workflow.resetSimulation();render()};const t=workflow.getTask(s.activeTask)||tasks.find(x=>workflow.getTaskStatus(x.id)!=='integrated')||tasks[0];content.querySelector('[data-sim-detail]').innerHTML=simTaskCard(t,s);bindSimTask(t,s);}
  function simTaskCard(t,s){const st=workflow.getTaskStatus(t.id),p=s.tasks[t.id]||{testsPrepared:false,codeReady:false,reviewAttempts:0,issue:'',fixReady:false};let body='';if(!s.started)body='<p>Симуляция ещё не запущена.</p>';else if(st==='blocked')body=`<p class="agent-blocked-reason">Задача ждёт интеграции: ${esc(t.dependsOn.filter(d=>workflow.getTaskStatus(d)!=='integrated').join(', '))}. Запуск заблокирован.</p>`;else if(st==='ready'&&!p.testsPrepared)body=`<div class="agent-stage-card"><b>1 · Test Designer</b><p>Получит задачу, контракт и критерии. Реализацию Builder он не видит.</p><details><summary>Промпт Test Designer</summary><pre>${esc(t.testPrompt)}</pre></details><button type="button" data-task-action="prepare-tests">Подготовить независимые тесты</button></div>`;else if(st==='testing_preparation')body=`<div class="agent-stage-card"><b>Test Designer готовит закрытый набор тестов</b><p>Вход: цель, контракт, критерии готовности. Доступа к реализации Builder нет.</p><pre>${esc(t.testPrompt)}</pre><button type="button" data-task-action="complete-tests">Зафиксировать тесты до реализации</button></div>`;else if(st==='ready'&&p.testsPrepared)body=`<div class="agent-stage-card"><b>Независимые тесты сохранены</b><p>Теперь Builder получает свою задачу, входы, контракты и моки. Закрытые тесты остаются у Reviewer.</p><details><summary>Промпт Builder и передаваемый контекст</summary><pre>${esc(t.builderPrompt)}\n\nВходы: ${esc(t.inputArtifacts.join(', '))}\nКонтракты: ${esc(t.contracts.join(', '))}\nМоки: ${esc(t.mocks.join(', '))}</pre></details><button type="button" data-task-action="start-builder">Передать задачу Builder</button></div>`;else if(st==='implementing')body=`<div class="agent-stage-card"><b>Builder · ${esc(t.branch)}</b><p>Имитация реализации на мок-данных. Builder не получает закрытые тесты Test Designer.</p><ul><li>Подготовка результата и локальных проверок</li><li>Источник данных: утверждённые фикстуры</li><li>Действия пользователя управляют переходом</li></ul><button type="button" data-task-action="complete-builder">Завершить демо-реализацию</button></div>`;else if(st==='reviewing')body=`<div class="agent-stage-card"><b>Reviewer · независимая проверка</b><p>Получены результат Builder, закрытые тесты, контракт и критерий готовности.</p><ul><li>Независимые тесты: ${p.testsPrepared?'подготовлены до реализации':'не подготовлены'}</li><li>Контракт: ${esc(t.contracts.join(', '))}</li><li>Попытка ревью: ${p.reviewAttempts+1} из 3</li></ul><button type="button" data-task-action="review">Запустить Reviewer</button></div>`;else if(st==='fixing')body=`<div class="agent-review-failure"><span>ЗАМЕЧАНИЕ REVIEWER · ПОПЫТКА ${p.reviewAttempts}/3</span><p>${esc(p.issue)}</p><p>До интеграции задача не допускается. Сначала Builder должен получить замечание и подготовить исправление.</p><button type="button" data-task-action="complete-fix">Передать замечание Builder · исправить</button></div>${p.fixReady?'<button type="button" data-task-action="review">Повторить ревью</button>':''}`;else if(st==='passed')body=`<div class="agent-review-pass"><b>✓ Ревью пройдено · ${p.reviewAttempts} попытка(и)</b><p>Тесты, контракт и критерии готовности приняты. До отдельного подтверждения интеграции задача не считается завершённой.</p><ul><li>Замечания Reviewer устранены</li><li>Зависимости для интеграции: ${esc(t.dependsOn.join(', ')||'нет')}</li><li>Предполагаемая ветка: ${esc(t.branch)}</li></ul><button type="button" data-task-action="integrate" ${t.dependsOn.some(d=>workflow.getTaskStatus(d)!=='integrated')?'disabled':''}>Условно интегрировать</button></div>`;else if(st==='failed')body=`<div class="agent-review-failure"><span>ЭСКАЛАЦИЯ · ТРИ НЕУДАЧНЫЕ ПОПЫТКИ</span><p>${esc(p.issue)}</p><p>Макора не переписывает код автоматически. Выберите дальнейший путь; задача остаётся неинтегрированной.</p><div class="agent-escalation-options">${workflow.optionsForEscalation(t.id).map(option=>`<button type="button" data-escalation-choice="${esc(option)}">${esc(option)}</button>`).join('')}</div><p data-escalation-status>${esc(s.escalation?.selected||'Решение пока не выбрано.')}</p></div>`;else if(st==='integrated')body=`<div class="agent-integrated"><b>✓ Условно интегрирована</b><p>${esc(t.result)}</p><p>Заменённая заглушка: ${esc((t.outputs||[]).join(', '))}</p><p>Предполагаемая ветка <code>${esc(t.branch)}</code> отмечена принятой только в симуляции. Реального merge не было.</p></div>`;
    return `<header class="agent-sim-card-header"><div><span class="agent-kicker">${esc(t.id)} · ${esc(statusLabel(st)).toUpperCase()}</span><h3>${esc(t.title)}</h3></div><span class="agent-priority">${esc(t.branch)}</span></header>${taskSummary(t)}${t.testUi?`<button type="button" class="agent-secondary" data-open-lab>Открыть внутренний тестовый интерфейс</button><div data-test-lab></div>`:''}<div class="agent-sim-actions">${body}</div>`}
  function bindSimTask(t,s){const detail=content.querySelector('[data-sim-detail]');detail.querySelectorAll('[data-task-action]').forEach(b=>b.onclick=()=>{const result=workflow.taskAction(t.id,b.dataset.taskAction);if(!result.ok){announce(result.error);return}simulation()});detail.querySelectorAll('[data-escalation-choice]').forEach(b=>b.onclick=()=>{const result=workflow.taskAction(t.id,'resolve-escalation',b.dataset.escalationChoice);if(!result.ok){announce(result.error);return}simulation()});detail.querySelector('[data-open-lab]')?.addEventListener('click',async()=>{await loadTestLab();const p=content.querySelector('.agent-test-lab');if(p)p.scrollIntoView({block:'nearest',behavior:'smooth'})})}
  function render(){const s=workflow.getState(),step=s.agent.currentView;updateTabs();content.scrollTop=0;if(agentMode==='real'&&window.makoraRealAgents){window.makoraRealAgents.render({board,content,status,primary,workflow,esc,announce,mode:agentMode});}else if(step==='skeleton')skeleton();else if(step==='decomposition')decomposition();else if(step==='map')map();else simulation();saveView();}
  function announce(message){let el=board.querySelector('.agent-announcement');if(!el){el=document.createElement('div');el.className='agent-announcement';el.setAttribute('role','status');board.querySelector('.agent-board-frame').prepend(el)}el.textContent=message;el.hidden=false;setTimeout(()=>{if(el.isConnected)el.hidden=true},5000)}
  board.querySelectorAll('[data-workflow-step]').forEach(b=>b.onclick=()=>{const result=workflow.openStep(b.dataset.workflowStep);if(!result.ok){announce(result.error);return}render()});
  board.querySelectorAll('[data-agent-mode]').forEach(b=>b.onclick=()=>{agentMode=b.dataset.agentMode;render()});
  board.querySelector('[data-agent-expand]').onclick=()=>{board.classList.toggle('agent-expanded');position();saveView()};
  board.addEventListener('dblclick',e=>{if(e.target.closest('button,textarea,input,label,select,summary,details'))return;board.classList.toggle('agent-expanded');position();saveView()});
  board.addEventListener('pointerdown',e=>{if(board.classList.contains('agent-expanded')||e.button!==0||e.target.closest('button,textarea,input,label,select,summary,details,.agent-board-content,.agent-board-footer'))return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,left:motion.targetX,top:motion.targetY,px:e.clientX,last:performance.now()};board.classList.add('agent-dragging');board.setPointerCapture(e.pointerId);e.preventDefault()});
  board.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;moved=true;motion.targetX=clamp(drag.left+e.clientX-drag.x,0,Math.max(0,innerWidth-board.offsetWidth));motion.targetY=clamp(drag.top+e.clientY-drag.y,0,Math.max(0,innerHeight-board.offsetHeight));const now=performance.now();motion.velocity=clamp((e.clientX-drag.px)/Math.max(.016,(now-drag.last)/1000),-1000,1000);drag.px=e.clientX;drag.last=now;startMotion()});
  function stopDrag(e){if(!drag||drag.id!==e.pointerId)return;drag=null;board.classList.remove('agent-dragging');saveView();startMotion();if(board.hasPointerCapture(e.pointerId))board.releasePointerCapture(e.pointerId)}
  ['pointerup','pointercancel','lostpointercapture'].forEach(type=>board.addEventListener(type,stopDrag));
  window.addEventListener('resize',()=>{if(!board.hidden&&!board.classList.contains('agent-expanded'))position()});
  window.addEventListener('makora-demo-workflow-change',e=>{if(board.hidden)return;if(workflow.getStep()==='decomposition'&&e.detail?.type==='task_changed')return;if(['task_changed','plan_invalidated','invalidation'].includes(e.detail?.type)){render()}});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&board.classList.contains('agent-expanded')){board.classList.remove('agent-expanded');position();saveView()}});
  function open(){if(!workflow.isDemoPrototypeReady())return false;const wasHidden=board.hidden;board.hidden=false;position();if(savedView.planExpanded)board.classList.add('agent-expanded');render();if(wasHidden){board.classList.remove('agent-revealing');void board.offsetWidth;board.classList.add('agent-revealing')}return true}
  return {position,open,close(){board.hidden=true;},isOpen(){return !board.hidden},element:board};
};
